def standard_ksb_texts(standard_ids):
    """``{standard_ksbs.id: (ksb_code, ksb_description)}`` for ``standard_ids``."""
    from django.db import connection
    from . import views
    wanted = {value for value in standard_ids if value is not None}
    if not wanted:
        return {}
    with _STANDARD_TEXTS_LOCK:
        if time.monotonic() - _STANDARD_TEXTS['read_at'] > STANDARD_TEXTS_TTL_SECONDS:
            _STANDARD_TEXTS.update(read_at=time.monotonic(), rows={})
        known = _STANDARD_TEXTS['rows']
        missing = wanted - known.keys()
    if missing:
        found = {}
        standards = views.authoring_table_name('standard_ksbs')
        with connection.cursor() as cursor:
            for chunk in _chunks(missing):
                placeholders = ', '.join(['%s'] * len(chunk))
                cursor.execute(
                    f'select id, ksb_code, ksb_description from {_only()}{standards} where id in ({placeholders})',
                    chunk,
                )
                found.update({sid: (code, description) for sid, code, description in cursor.fetchall()})
        with _STANDARD_TEXTS_LOCK:
            known.update(found)
    return {value: known[value] for value in wanted if value in known}

views.py:column_names.source:
def column_names(table):
    global _TABLE_COLUMNS_LISTED
    if native_only():
        from .free_course_contract import COLUMNS
        if table in COLUMNS:
            return {name for name, _ in COLUMNS[table]}
    cache_key = f'{CURRICULUM_SCHEMA}.{table}'
    if cache_key in _TABLE_COLUMNS_CACHE:
        return _TABLE_COLUMNS_CACHE[cache_key]

    if connection.vendor == 'postgresql':
        if not _TABLE_COLUMNS_LISTED:
            # The first miss in a process lists every curriculum table's columns
            # in one query. A cold process used to ask once per table -- a dozen
            # trips to the remote database (~4 s) before a programme page's first
            # build could start. The answer per table is the same query's: the
            # same view, filtered the same way. Only the first miss lists: a key
            # dropped later (after an ALTER) and a table the listing did not name
            # are asked about on their own below, exactly as before.
            listed = defaultdict(set)
            for row in fetch_all(
                'select table_name, column_name from information_schema.columns where table_schema = %s',
                [CURRICULUM_SCHEMA],
            ):
                listed[row['table_name']].add(row['column_name'])
            for name, names in listed.items():
                _TABLE_COLUMNS_CACHE.setdefault(f'{CURRICULUM_SCHEMA}.{name}', names)
            _TABLE_COLUMNS_LISTED = True
            if cache_key in _TABLE_COLUMNS_CACHE:
                return _TABLE_COLUMNS_CACHE[cache_key]
        rows = fetch_all(
            '''
            select column_name
            from information_schema.columns
            where table_schema = %s and table_name = %s
            ''',
            [CURRICULUM_SCHEMA, table],
        )
        names = {row['column_name'] for row in rows}
    else:
        with connection.cursor() as cursor:
            cursor.execute(f'pragma table_info({quote_ident(table)})')
            names = {row[1] for row in cursor.fetchall()}
    _TABLE_COLUMNS_CACHE[cache_key] = names
    return names
